const ELEMENT_PROP_KEYS = new Set(["theme","tagline","layers","push","depthBlur","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "light",
  tagline: "Launch films, cut from components.",
  layers: 5,
  push: 132,
  depthBlur: 1,
  fontFamily: "Hanken Grotesk",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type LayeredCutoutElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof LayeredCutoutBase>;

const LayeredCutoutInner = forwardRef<
  HTMLDivElement,
  LayeredCutoutElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<LayeredCutout>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <LayeredCutoutBase
          {...(componentProps as unknown as ComponentProps<typeof LayeredCutoutBase>)}
        />
      </div>
    </Sequence>
  );
});

export const LayeredCutout = Interactive.withSchema({
  Component: LayeredCutoutInner,
  componentName: "<LayeredCutout>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
